import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';

const PORT = 9515;
const BASE = 'http://127.0.0.1:8789';
const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
chrome.stderr.on('data', d => console.error('[driver]', String(d).trim()));

async function wd(method, path, body) {
  const response = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: body ? { 'content-type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30000)
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(`${method} ${path} -> ${response.status} ${JSON.stringify(payload)}`);
  return payload;
}

const idOf = found => found.value['element-6066-11e4-a52e-4f735466cecf'] ?? found.value.ELEMENT;

try {
  for (let i = 0; i < 60; i++) {
    try { await fetch(`http://127.0.0.1:${PORT}/status`); break; } catch { await delay(250); }
  }
  const session = await wd('POST', '/session', { capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { binary: '/usr/bin/google-chrome', args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu', '--log-level=SEVERE'] } } } });
  const sid = session.sessionId ?? session.value?.sessionId;
  const call = (m, p, b) => wd(m, `/session/${sid}${p}`, b);
  await call('POST', '/url', { url: `${BASE}/?grams=500&dest=tel-aviv` });
  await delay(4000);
  const before = await call('POST', '/execute/sync', { script: 'return {search: location.search, total: document.querySelector(".best__total")?.textContent, states: [...document.querySelectorAll("#quantity-group button")].map(b=>[b.textContent,b.getAttribute("aria-pressed")])}', args: [] });
  console.log('BEFORE', JSON.stringify(before.value));
  const found = await call('POST', '/element', { using: 'css selector', value: '#quantity-group button[data-grams="1000"]' });
  const id = idOf(found);
  console.log('ELEMENT ID', id);
  const rect = await call('GET', `/element/${id}/rect`);
  console.log('RECT', JSON.stringify(rect.value));
  const clicked = await call('POST', `/element/${id}/click`, {});
  console.log('CLICK', JSON.stringify(clicked.value ?? null));
  await delay(4000);
  const after = await call('POST', '/execute/sync', { script: 'return {search: location.search, total: document.querySelector(".best__total")?.textContent, states: [...document.querySelectorAll("#quantity-group button")].map(b=>[b.textContent,b.getAttribute("aria-pressed")]), bodyState: document.body.dataset.boardState, text: document.body.innerText.slice(0,300)}', args: [] });
  console.log('AFTER', JSON.stringify(after.value, null, 1));
  const logs = await call('POST', '/log', { type: 'browser' });
  console.log('LOGS', JSON.stringify(logs.value ?? logs, null, 1).slice(0, 2000));
  await call('DELETE', '/session');
} catch (error) {
  console.error('DEBUG ERROR', error);
} finally {
  chrome.kill('SIGTERM');
  process.exit(0);
}

