    const demo = terms2000.best;
    assert?? no assert in script; use checks
    if (!demo || !demo.vendor.id.includes('qa-terms-demo')) ... hmm
    await wd('POST', '/url', { url: `${termsServer.url}/?grams=2000&dest=tel-aviv` });
    await waitForBoard(wd);
    const terms = await evaluate(wd, `(() => {
      const dl = document.querySelector('.best__side dl');
      const dts = dl ? [...dl.querySelectorAll('dt')] : [];
      const dds = dl ? [...dl.querySelectorAll('dd')] : [];
      return {
        rows: dts.map((dt, index) => [dt.textContent.trim(), (dds[index]?.textContent ?? '').trim()]),
        total: document.querySelector('.best__total')?.textContent ?? null,
        labels: [...document.querySelectorAll('.best__side .unknown__reason')].map(n => n.textContent.trim())
      };
    })()`);
    const expectedTermsTotal = ils(terms2000.best?.totalIls);
    check('terms: demo offer is the ranked best for 2 kg', terms2000.best?.vendor.id === 'qa-terms-demo' && terms.total === expectedTermsTotal, `${terms.total} vs ${expectedTermsTotal} (${terms2000.best?.vendor.id})`);
    check('terms: minimum order is displayed', terms.rows.some(([term, value]) => term === 'Minimum order' && value === '₪30.00 ILS'), JSON.stringify(terms.rows));
    check('terms: free-shipping threshold is displayed', terms.rows.some(([term, value]) => term === 'Free shipping' && value === 'from ₪100.00 ILS'), JSON.stringify(terms.rows));
    check('terms: locality-restricted delivery area is displayed', terms.rows.some(([term, value]) => term === 'Delivery area' && value === 'Only: tel-aviv, eilat'), JSON.stringify(terms.rows));
    check('terms: free-shipping threshold met is labelled and shipping shows Free', terms.rows.some(([term, value]) => term === 'Shipping' && value === 'Free') && terms.labels.some(t => t.includes('Free shipping threshold met')), JSON.stringify(terms.labels));
    // Restriction actually excludes the offer for Jerusalem.
    await wd('POST', '/url', { url: `${termsServer.url}/?grams=2000&dest=jerusalem` });
    await waitForBoard(wd);
    const restricted = await evaluate(wd, `(() => ({
      bestVendor: document.querySelector('.best__vendor')?.textContent ?? null,
      reasons: [...document.querySelectorAll('.unknown__reason')].map(n => n.textContent.trim())
    }))()`);
    check('terms: locality restriction moves the demo offer to the unknown list for Jerusalem',
      restricted.reasons.some(text => text.includes('does not include')), JSON.stringify(restricted.reasons));
  } finally {
    await termsServer.close();
  }
```

Careful: `report.sessionClosed` etc. Also the `finally` in the outer try handles fixtureServer close; the inner try/finally closes termsServer.

One catch: after navigation to the terms server, `waitForBoard` expects `document.body.dataset.boardState === 'ready' && .best/.empty`. Fine.

Another catch: `const demo = terms2000.best` — if not the demo, the check fails but subsequent DOM rows may differ; checks still run and fail individually. Fine.

Also careful: With `?grams=2000&dest=jerusalem`, CoffeeMan ranks (country-wide) and demo is unrankable; `.unknown__reason` for demo includes "Vendor delivery list does not include Jerusalem". Good.

Wait — do I need `fetchBoard(termsServer.url, ...)` with variant classico? yes, function does that.

