content.text:
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { runRefresh, maybeInitialRefresh, backoffMs, REFRESH_INTERVAL_MS, BACKOFF_BASE_MS } from '../src/refresh.js';
import { createMemoryStore } from '../src/store.js';
import { registeredVendors } from '../src/vendors/index.js';

const fixtures = new URL('./fixtures/', import.meta.url);
const coffeemanBytes = readFileSync(new URL('coffeeman-product.windows-1255.html', fixtures));
const coffeeman4Bytes = readFileSync(new URL('coffeeman-4pack-product.windows-1255.html', fixtures));
const coffeeman8Bytes = readFileSync(new URL('coffeeman-8pack-product.windows-1255.html', fixtures));
const coffeemanOosBytes = readFileSync(new URL('coffeeman-product.outofstock.windows-1255.html', fixtures));
const pucksHtml = readFileSync(new URL('pucks-product.html', fixtures), 'utf8');

const BOI = {
  exchangeRates: [
    { key: 'USD', currentExchangeRate: 3.05, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' },
    { key: 'EUR', currentExchangeRate: 3.55, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' }
  ]
};

function fixtureFetch({ coffeeman = coffeemanBytes, fourPack = coffeeman4Bytes, eightPack = coffeeman8Bytes, failCoffeeman = false, failFx = false, calls = [] } = {}) {
  return async url => {
    calls.push(url);
    if (url.includes('coffeeman.co.il')) {
      if (failCoffeeman) return new Response('vendor down', { status: 503 });
      const bytes = url.includes('4-%D7%90%D7%A8%D7%99%D7%96%D7%95%D7%AA') ? fourPack
        : url.includes('8-%D7%90%D7%A8%D7%99%D7%96%D7%95%D7%AA') ? eightPack
        : coffeeman;
      return new Response(bytes, { status: 200, headers: { 'content-type': 'text/html; charset=windows-1255' } });
    }
    if (url.includes('pucks.co.il')) {
      return new Response(pucksHtml, { status: 200, headers: { 'content-type': 'text/html' } });
    }
    if (url.includes('boi.org.il')) {
      if (failFx) return new Response('fx down', { status: 500 });
      return Response.json(BOI);
    }
    return new Response('unexpected', { status: 404 });
  };
}

const NOW = Date.parse('2026-10-12T12:00:00.000Z');

test('scheduled refresh persists observations without a browser', async () => {
  const store = createMemoryStore();
  const calls = [];
  const summary = await runRefresh({ store, fetchImpl: fixtureFetch({ calls }), now: NOW, trigger: 'cron' });
  assert.equal(summary.trigger, 'cron');
  assert.equal(summary.vendors.length, 2);
  assert.equal(summary.requests, 5, 'three CoffeeMan listings plus Pucks and one FX request');
  const snapshot = await store.snapshot();
  assert.equal(snapshot.observations.length, 4);
  const coffeeman = snapshot.observations.find(o => o.vendor.id === 'coffeeman');
  assert.equal(coffeeman.price.amount, 33);
  assert.equal(coffeeman.attemptedAt, new Date(NOW).toISOString());
  assert.equal(snapshot.meta.fx.rates.USD.rate, 3.05);
  assert.equal(snapshot.meta.fx.asOf, '2026-10-09T09:21:04.476265Z');
  assert.ok(snapshot.meta.lastRefreshAt.value);
  const vendorState = await store.getVendorState('pucks');
  assert.equal(vendorState.consecutiveFailures, 0);
  assert.equal(Date.parse(vendorState.nextAttemptAt), NOW + REFRESH_INTERVAL_MS);
});

test('one failing vendor keeps its previous good observation and does not block the other', async () => {
  const store = createMemoryStore();
  await runRefresh({ store, fetchImpl: fixtureFetch(), now: NOW });
  const before = (await store.snapshot()).observations.find(o => o.vendor.id === 'coffeeman');
  assert.equal(before.price.amount, 33);

  const second = await runRefresh({
    store,
    fetchImpl: fixtureFetch({ failCoffeeman: true }),
    now: NOW + REFRESH_INTERVAL_MS + 1000
  });
  const coffeemanResult = second.vendors.find(v => v.vendorId === 'coffeeman');
  assert.equal(coffeemanResult.ok, false);
  const pucksResult = second.vendors.find(v => v.vendorId === 'pucks');
  assert.equal(pucksResult.ok, true);

  const snapshot = await store.snapshot();
  const kept = snapshot.observations.find(o => o.vendor.id === 'coffeeman');
  assert.equal(kept.price.amount, 33, 'previous good price is preserved');
  assert.equal(kept.observedAt, before.observedAt, 'last successful observation timestamp is unchanged');
  assert.ok(kept.attemptedAt, 'failed attempt timestamp is recorded');
  const attempts = await store.listRuns(5);
  assert.equal(attempts[0].vendors.find(v => v.vendorId === 'coffeeman').failures.length, 3, 'all three CoffeeMan listings report the failure');
});

test('repeated failures back off and stop re-fetching the broken vendor', async () => {
  const store = createMemoryStore();
  const first = await runRefresh({ store, fetchImpl: fixtureFetch({ failCoffeeman: true }), now: NOW });
  assert.equal(first.vendors.find(v => v.vendorId === 'coffeeman').ok, false);
  const state = await store.getVendorState('coffeeman');
  assert.equal(state.consecutiveFailures, 1);
  assert.equal(Date.parse(state.nextAttemptAt), NOW + BACKOFF_BASE_MS);

  const calls = [];
  const second = await runRefresh({ store, fetchImpl: fixtureFetch({ failCoffeeman: true, calls }), now: NOW + 5 * 60 * 1000 });
  assert.equal(second.vendors.find(v => v.vendorId === 'coffeeman').skipped, true);
  assert.equal(calls.some(url => url.includes('coffeeman')), false, 'vendor in backoff is not fetched');
  assert.equal(backoffMs(2), 60 * 60 * 1000);
  assert.equal(backoffMs(10), 12 * 60 * 60 * 1000);
});

test('a failing FX fetch keeps the previous rate table', async () => {
  const store = createMemoryStore();
  await runRefresh({ store, fetchImpl: fixtureFetch(), now: NOW });
  const fx = (await store.snapshot()).meta.fx;
  assert.equal(fx.rates.USD.rate, 3.05);
  await runRefresh({ store, fetchImpl: fixtureFetch({ failFx: true }), now: NOW + REFRESH_INTERVAL_MS });
  const after = (await store.snapshot()).meta.fx;
  assert.equal(after.rates.USD.rate, 3.05, 'previous rates preserved when the feed fails');
  assert.equal(after.asOf, fx.asOf);
});

test('out-of-stock observation replaces the price but never claims availability', async () => {
  const store = createMemoryStore();
  await runRefresh({ store, fetchImpl: fixtureFetch(), now: NOW });
  const summary = await runRefresh({
    store,
    fetchImpl: fixtureFetch({ coffeeman: coffeemanOosBytes }),
    now: NOW + REFRESH_INTERVAL_MS
  });
  assert.equal(summary.vendors.find(v => v.vendorId === 'coffeeman').ok, true);
  const observation = (await store.snapshot()).observations.find(o => o.vendor.id === 'coffeeman');
  assert.equal(observation.availability, 'out_of_stock');
});

test('leases prevent concurrent refresh runs', async () => {
  const store = createMemoryStore();
  const gate = new Promise(resolve => setTimeout(resolve, 15));
  const slowFetch = async url => {
    await gate;
    return fixtureFetch()(url);
  };
  const first = runRefresh({ store, fetchImpl: slowFetch, now: NOW });
  await new Promise(resolve => setTimeout(resolve, 2));
  const second = await runRefresh({ store, fetchImpl: fixtureFetch(), now: NOW });
  assert.equal(second.skipped, true);
  await first;
});

test('refresh runs started in the same tick cannot both acquire the lease', async () => {
  const store = createMemoryStore();
  const calls = [];
  const [first, second] = await Promise.all([
    runRefresh({ store, fetchImpl: fixtureFetch({ calls }), now: NOW }),
    runRefresh({ store, fetchImpl: fixtureFetch({ calls }), now: NOW })
  ]);
  const summaries = [first, second];
  assert.equal(summaries.filter(summary => summary.skipped).length, 1, 'exactly one run is skipped');
  assert.equal(summaries.find(summary => !summary.skipped).requests, 5);
  assert.equal(calls.length, 5, 'the losing run performs no vendor or FX requests');
});

test('initial refresh runs once and is throttled afterwards', async () => {
  const store = createMemoryStore();
  const started = await maybeInitialRefresh({ store, ctx: null, now: NOW, run: async () => ({ ran: true }), vendors: [], includeFx: false });
  assert.equal(started.started, true);
  const triggered = await maybeInitialRefresh({ store, ctx: null, now: NOW + 1000 });
  assert.equal(triggered.skipped, true);
  const waited = await maybeInitialRefresh({ store, ctx: null, now: NOW + 20 * 60 * 1000, run: async () => ({ ran: true }), vendors: [], includeFx: false });
  assert.equal(waited.started, true);
});

test('allowlist blocks requests to hosts outside the vendor registry', async () => {
  const store = createMemoryStore();
  const calls = [];
  const hostileFetch = async url => {
    calls.push(url);
    return new Response('ok');
  };
  await runRefresh({
    store,
    vendors: [{
      id: 'fake',
      name: 'Fake',
      homepage: 'https://fake.test',
      allowedHosts: ['allowed.test'],
      parserVersion: 'fake/1',
      offers: [{ id: 'x', url: 'https://allowed.test/p' }],
      async observe({ fetchText }) {
        const denied = await fetchText('https://evil.test/p');
        assert.equal(denied.ok, false);
        assert.match(denied.error, /not allowed/);
        return { observations: [], failures: [{ offerId: 'x', error: 'no data' }] };
      }
    }],
    fetchImpl: hostileFetch,
    now: NOW
  });
  assert.deepEqual(calls.filter(url => url.includes('evil.test')), [], 'no network request is made for a non-allowlisted host');
  assert.deepEqual(calls, ['https://www.boi.org.il/currency.xml'], 'only the allowlisted FX host is contacted');
});

test('registered vendors are within their own allowlists', async () => {
  for (const vendor of registeredVendors()) {
    for (const offer of vendor.offers) {
      const host = new URL(offer.url).hostname;
      assert.ok(vendor.allowedHosts.includes(host), `${vendor.id} allowlists ${host}`);
    }
    assert.ok(vendor.parserVersion, `${vendor.id} has a parser version`);
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { quoteBoard, quoteOffer, findDestination } from '../src/lib/quote.js';

const NOW = Date.parse('2026-10-12T12:00:00.000Z');
const FRESH = '2026-10-12T09:00:00.000Z';
const STALE = '2026-10-10T09:00:00.000Z';

function observation(overrides = {}) {
  const base = {
    key: 'vendor:sku',
    vendor: { id: 'vendor', name: 'Vendor', homepage: 'https://vendor.test' },
    itemUrl: 'https://vendor.test/p/1',
    product: {
      productId: 'lavazza-crema-e-gusto-vacuum-ground',
      name: 'Lavazza Crema e Gusto Classico 250 g ground',
      variantId: 'classico',
      variantLabel: 'Classico',
      form: 'ground',
      packGrams: 250,
      packCount: 1,
      totalGrams: 250,
      sku: 'sku-1'
    },
    price: { amount: 40, currency: 'ILS' },
    availability: 'in_stock',
    shipping: {
      mode: 'delivery',
      certainty: 'verified',
      amount: { amount: 20, currency: 'ILS' },
      destination: { scope: 'country', country: 'IL' }
    },
    observedAt: FRESH
  };
  return {
    ...base,
    ...overrides,
    product: { ...base.product, ...(overrides.product ?? {}) },
    shipping: { ...base.shipping, ...(overrides.shipping ?? {}) },
    price: { ...base.price, ...(overrides.price ?? {}) }
  };
}

const quote = (observations, options = {}) => quoteBoard({
  observations,
  productId: 'lavazza-crema-e-gusto-vacuum-ground',
  targetGrams: 500,
  destination: findDestination('tel-aviv'),
  now: NOW,
  ...options
});

test('shipping can change the winner: cheap item with expensive delivery loses', () => {
  const cheapItemPriceyShipping = observation({
    key: 'expensive-shipping:1',
    vendor: { id: 'a', name: 'Cheap item, pricey delivery' },
    price: { amount: 30, currency: 'ILS' },
    shipping: { certainty: 'verified', amount: { amount: 40, currency: 'ILS' } }
  });
  const pricierItemCheapShipping = observation({
    key: 'cheap-shipping:1',
    vendor: { id: 'b', name: 'Higher item, cheap delivery' },
    price: { amount: 45, currency: 'ILS' },
    shipping: { certainty: 'verified', amount: { amount: 5, currency: 'ILS' } }
  });
  const board = quote([cheapItemPriceyShipping, pricierItemCheapShipping]);
  assert.equal(board.best.vendor.id, 'b');
  assert.equal(board.best.totalIls, 95); // 2 packs × 45 + 5 shipping
});

test('unknown shipping cannot win and is never treated as zero', () => {
  const known = observation({ key: 'known:1', price: { amount: 50 }, shipping: { certainty: 'verified', amount: { amount: 10, currency: 'ILS' } } });
  const unknown = observation({
    key: 'unknown:1',
    vendor: { id: 'u', name: 'Unknown shipping' },
    price: { amount: 10 },
    shipping: { certainty: 'unknown', amount: null, note: 'Calculated at checkout' }
  });
  const board = quote([known, unknown]);
  assert.equal(board.best.key, 'known:1');
  assert.equal(board.ranked.length, 1);
  const blocked = [...board.unrankable, ...board.staleOrUnavailable].find(item => item.key === 'unknown:1');
  assert.equal(blocked.totalIls, null);
  assert.match(blocked.reasons.join(' '), /unknown, not free/);
});

test('stale and out-of-stock observations stay visible but unranked', () => {
  const fresh = observation({ key: 'fresh:1' });
  const stale = observation({ key: 'stale:1', observedAt: STALE });
  const outOfStock = observation({ key: 'oos:1', availability: 'out_of_stock' });
  const board = quote([fresh, stale, outOfStock]);
  assert.deepEqual(board.ranked.map(q => q.key), ['fresh:1']);
  assert.equal(board.staleOrUnavailable.length, 2);
  const staleQuote = board.staleOrUnavailable.find(q => q.key === 'stale:1');
  assert.equal(staleQuote.rankable, false);
  assert.match(staleQuote.labels.join(' '), /Stale/);
  const oosQuote = board.staleOrUnavailable.find(q => q.key === 'oos:1');
  assert.match(oosQuote.labels.join(' '), /Out of stock/);
});

test('availability unknown is not shown as confirmed available', () => {
  const board = quote([observation({ key: 'maybe:1', availability: 'unknown' })]);
  assert.equal(board.ranked.length, 0);
  const entry = board.staleOrUnavailable[0];
  assert.match(entry.reasons.join(' '), /cannot be confirmed as available/);
});

test('variants and multipacks are not merged: variant stays in identity and per-kg normalizes', () => {
  const single = observation({ key: 'single:1', price: { amount: 30 }, shipping: { amount: { amount: 0, currency: 'ILS' } } });
  const multipack = observation({
    key: 'multi:1',
    product: { packGrams: 250, packCount: 4, totalGrams: 1000 },
    price: { amount: 100 },
    shipping: { amount: { amount: 15, currency: 'ILS' } }
  });
  const forte = observation({
    key: 'forte:1',
    product: { variantId: 'forte', variantLabel: 'Forte' },
    price: { amount: 20 },
    shipping: { amount: { amount: 0, currency: 'ILS' } }
  });
  const board = quote([single, multipack, forte]);
  assert.equal(board.ranked.length, 3);
  // 500 g target: single needs 2 packs (₪60), multipack needs 1 unit (₪115), forte needs 2 packs (₪40).
  const byKey = Object.fromEntries(board.ranked.map(q => [q.key, q]));
  assert.equal(byKey['single:1'].units, 2);
  assert.equal(byKey['single:1'].orderedGrams, 500);
  assert.equal(byKey['single:1'].ilsPerKg, 120);
  assert.equal(byKey['multi:1'].units, 1);
  assert.equal(byKey['multi:1'].ilsPerKg, 115);
  assert.equal(byKey['multi:1'].product.variantLabel, 'Classico');
  assert.equal(byKey['forte:1'].product.variantLabel, 'Forte');
  assert.equal(byKey['forte:1'].ilsPerKg, 80);
});

test('quantity changes units and totals without losing pack rounding', () => {
  const offer = observation({ price: { amount: 30 }, shipping: { amount: { amount: 10, currency: 'ILS' } } });
  const at100 = quoteOffer(offer, { grams: 100, destination: findDestination('tel-aviv'), fx: null, now: NOW, staleAfterMs: 24 * 3600 * 1000 });
  assert.equal(at100.units, 1);
  assert.equal(at100.totalIls, 40);
  const at600 = quoteOffer(offer, { grams: 600, destination: findDestination('tel-aviv'), fx: null, now: NOW, staleAfterMs: 24 * 3600 * 1000 });
  assert.equal(at600.units, 3);
  assert.equal(at600.orderedGrams, 750);
  assert.equal(at600.totalIls, 100);
});

test('free-shipping threshold and minimum order are calculated, not guessed', () => {
  const threshold = observation({
    key: 'threshold:1',
    price: { amount: 30 },
    shipping: { certainty: 'verified', amount: { amount: 20, currency: 'ILS' }, freeThreshold: { amount: 60, currency: 'ILS' } }
  });
  const below = quoteOffer(threshold, { grams: 250, destination: findDestination('tel-aviv'), now: NOW, staleAfterMs: 1e12 });
  assert.equal(below.totalIls, 50);
  const above = quoteOffer(threshold, { grams: 500, destination: findDestination('tel-aviv'), now: NOW, staleAfterMs: 1e12 });
  assert.equal(above.totalIls, 60);
  assert.match(above.labels.join(' '), /Free shipping threshold met/);

  const minimum = observation({
    key: 'min:1',
    price: { amount: 15 },
    shipping: { certainty: 'verified', amount: { amount: 0, currency: 'ILS' }, minOrder: { amount: 50, currency: 'ILS' } }
  });
  const board = quote([minimum]);
  assert.equal(board.ranked.length, 0);
  assert.match(board.unrankable[0].reasons.join(' '), /minimum order/);
});

test('missing FX never becomes zero and cannot be ranked', () => {
  const usd = observation({
    key: 'usd:1',
    price: { amount: 20, currency: 'USD' },
    shipping: { certainty: 'verified', amount: { amount: 5, currency: 'USD' } }
  });
  const withoutFx = quote([usd]);
  assert.equal(withoutFx.ranked.length, 0);
  assert.match(withoutFx.unrankable[0].reasons.join(' '), /no USD reference rate is stored/i);
  const withFx = quote([usd], { fx: { asOf: '2026-10-09', base: 'ILS', rates: { USD: { rate: 3, unit: 1 } }, source: { name: 'test' } } });
  assert.equal(withFx.best.totalIls, 135); // 2 packs × $20 + $5 shipping = $45 × 3
  assert.equal(withFx.best.estimate, true);
});

test('destination restrictions are enforced for coverage lists', () => {
  const localOnly = observation({
    key: 'local:1',
    shipping: { destination: { scope: 'localities', localities: ['haifa'] } }
  });
  const telAviv = quote([localOnly]);
  assert.equal(telAviv.ranked.length, 0);
