  if (og) return decodeEntities(collapse(String(og).replace(/\s*-\s*₪[\d.,]+\s*$/, '')));
  const title = /<title>([\s\S]*?)<\/title>/i.exec(html)?.[1];
  return title ? decodeEntities(collapse(stripTags(title).split('|')[0])) : null;
}

