/** Extract original bytes from `from` to the end of `to`, searched in order. */
function between(buf, from, to, { back = 0, include = 0 } = {}) {
  let start = buf.indexOf(from);
  if (start < 0) throw new Error(`anchor not found: ${from}`);
  if (back) {
    const slice = buf.subarray(0, start).toString('latin1');
    const idx = slice.lastIndexOf(back);
    if (idx < 0) throw new Error(`back anchor not found: ${back}`);
    start = idx;
  }
  const endIdx = buf.indexOf(to, start + from.length);
  if (endIdx < 0) throw new Error(`end anchor not found: ${to}`);
  return buf.subarray(start, endIdx + to.length + include);
}

