  const eight = parseCoffeemanProduct(decodeHtml(read('coffeeman-qualita-oro-8pack-product.windows-1255.html')), { now, productId: 'lavazza-qualita-oro-vacuum-ground' });
  assert.equal(eight.product.packCount, 8);
